'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var SMALLEST_SUBNORMAL = require( '@stdlib/constants/float32/smallest-subnormal' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var ldexpf = require( '@stdlib/math/base/special/ldexpf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var round2f = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( round2f instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof round2f, 'function', 'main export is a function' );
	t.end();
});

tape( 'returns +0 for +0', opts, function test( t ) {
	var v = round2f( +0.0 );
	t.strictEqual( isPositiveZerof( v ), true );
	t.end();
});

tape( 'returns -0 for -0', opts, function test( t ) {
	var v = round2f( -0.0 );
	t.strictEqual( isNegativeZerof( v ), true );
	t.end();
});

tape( 'returns NaN for NaN', opts, function test( t ) {
	var v = round2f( NaN );
	t.strictEqual( isnanf( v ), true );
	t.end();
});

tape( 'returns infinities unchanged', opts, function test( t ) {
	t.strictEqual( round2f( PINF ), PINF );
	t.strictEqual( round2f( NINF ), NINF );
	t.end();
});

tape( 'returns smallest subnormal unchanged', opts, function test( t ) {
	var v = round2f( SMALLEST_SUBNORMAL );
	t.strictEqual( v, SMALLEST_SUBNORMAL );
	t.end();
});

tape( 'supports rounding large values', opts, function test( t ) {
	var x;
	var v;

	x = ldexpf( 1.0, 127 );
	v = round2f( x + ( x / 3.0 ) );
	t.strictEqual( v, x );

	x = -ldexpf( 1.0, 127 );
	v = round2f( x + ( x / 3.0 ) );
	t.strictEqual( v, x );

	t.end();
});

tape( 'rounds to nearest power of two', opts, function test( t ) {
	t.strictEqual( round2f( 3.0 ), 4.0 );
	t.strictEqual( round2f( 6.0 ), 8.0 );
	t.strictEqual( round2f( 9.5 ), 8.0 );
	t.strictEqual( round2f( 12.0 ), 16.0 );
	t.strictEqual( round2f( 0.3 ), 0.25 );
	t.strictEqual( round2f( -0.3 ), -0.25 );
	t.end();
});
